def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_d = 0
    my_d = 0
    recent_opp_d = 0
    recent_my_d = 0
    run_opp_d = 0

    for i, (me, opp) in enumerate(history):
        if opp == 'D':
            opp_d += 1
        if me == 'D':
            my_d += 1
        if n - i <= 10:
            if opp == 'D':
                recent_opp_d += 1
            if me == 'D':
                recent_my_d += 1

    for me, opp in reversed(history):
        if opp == 'D':
            run_opp_d += 1
        else:
            break

    defect_rate = opp_d / n
    last_me, last_opp = history[-1]

    punished = 0
    forgiven = 0
    for i in range(1, n):
        prev_me, prev_opp = history[i - 1]
        if prev_me == 'D' and prev_opp == 'C':
            if history[i][1] == 'C':
                forgiven += 1
            else:
                punished += 1

    if n >= 8 and (defect_rate > 0.65 or (recent_opp_d >= 8 and defect_rate > 0.50)):
        if defect_rate < 0.80 and rng.random() < 0.04:
            return 'C'
        return 'D'

    if last_opp == 'D':
        if run_opp_d >= 2 and n >= 85:
            if last_me == 'C':
                return 'D'
            if defect_rate < 0.50 and opp_d <= n // 2 and rng.random() < 0.45:
                return 'C'
            return 'D'

        if run_opp_d >= 3:
            if last_me == 'D' and defect_rate < 0.50 and opp_d <= n // 3:
                if rng.random() < 0.40:
                    return 'C'
            return 'D'

        if defect_rate < 0.25 and opp_d <= max(2, n // 12):
            if rng.random() < 0.75:
                return 'C'

        if last_me == 'D' and defect_rate < 0.50 and recent_opp_d <= 3:
            if rng.random() < 0.45:
                return 'C'

        if defect_rate < 0.45:
            if rng.random() < 0.30:
                return 'C'
            return 'D'

        if defect_rate < 0.65:
            if rng.random() < 0.12:
                return 'C'
            return 'D'

        return 'D'

    max_defects = n // 8 + 1
    if opp_d == 0:
        if n >= 98:
            return 'D'
        if my_d == 1 and last_me == 'D' and last_opp == 'C':
            return 'C'
        if my_d == 0 and n >= 12:
            return 'D'
        if my_d < max_defects and recent_my_d <= 2:
            p = 0.12
            if n >= 30:
                p = 0.20
            if n >= 60:
                p = 0.28
            if n >= 80:
                p = 0.36
            if recent_my_d >= 1:
                p -= 0.05
            if p > 0.0 and rng.random() < p:
                return 'D'
        return 'C'

    if (last_me == 'D' and punished == 0 and forgiven >= 1 and
            defect_rate < 0.15 and recent_opp_d <= 1 and recent_my_d <= 2 and my_d < 12):
        if rng.random() < 0.40:
            return 'D'

    if defect_rate < 0.12 and recent_opp_d == 0 and punished == 0:
        if n >= 90 and my_d < 14 and recent_my_d <= 2:
            if rng.random() < 0.45:
                return 'D'
        if n >= 96 and my_d < 16 and recent_my_d <= 3:
            return 'D'

    if defect_rate < 0.30:
        return 'C'
    if defect_rate < 0.50:
        if rng.random() < 0.75:
            return 'C'
        return 'D'

    return 'D'
